82:   if (capability === undefined || capability === null) {
83:     return {
84:       ok: false,
85:       code: "capability-required",
86:       reason: "岗位实例调用组织命令必须携带 host 签发的 capability 信封（bot 不能自请）"
87:     };
88:   }
89:   if (!isCapabilityEnvelope(capability)) {
90:     return { ok: false, code: "capability-malformed", reason: "信封须为严格 {payload, sig}（fail closed）" };
91:   }
92:   const verdict = issuer.verify({ envelope: capability, botId: actor.id, taskId, op, consumeNonce });
93:   if (!verdict.ok) return verdict; // 腿一/腿三码：capability-*／task-domain-mismatch／instance-not-alive…
94:   const home = postForBot?.(actor.id) ?? null;
95:   if (home === null || OP_SET[home] === undefined) {
96:     return {
97:       ok: false,
98:       code: "post-unassigned",
99:       reason: `实例 ${String(actor.id)} 未绑定 home 岗位（岗位白名单无从判定，fail closed）`
100:     };
101:   }
102:   if (!availableOps(home, verdict.payload).includes(op)) {
103:     return {
104:       ok: false,
105:       code: "op-not-in-opset",
106:       reason: `op ${String(op)} 不在 ${home} 岗位表 ∪ 当次签发集（工具面裁剪＝权限裁剪）`
107:     };
108:   }
