114:  * home 岗位解析（宿主接线读注册表 `post` 字段）。返回 `authorize(ctx)` 供
115:  * `createTaskLedger({ authorize })` 装入；ctx＝{op, taskId, actor, capability}。
116:  * 三元组＝实例活态／op 白名单／任务域匹配，三腿实现见 `postCapabilityVerdict`。
117:  */
118: export function createLedgerAuthorizer({ issuer, postForBot } = {}) {
119:   if (!issuer || typeof issuer.verify !== "function") {
120:     throw new Error("createLedgerAuthorizer 需要 capability 签发/验签门面");
121:   }
122:   function authorize({ op, taskId, actor, capability } = {}) {
123:     if (!actor || actor.kind !== "post") return { ok: true }; // user＝台账全权；host＝进程内确定性组件
124:     return postCapabilityVerdict({ issuer, postForBot, actor, capability, op, taskId });
125:   }
126:   return { authorize };
