129: /**
130:  * 命令 dispatch（签发联动薄封装）：**链式能力**——命令是单次消费的，所以每个
131:  * 授权有效的岗位命令返回件都必须携带下一张能力，否则持有者在下一次命令后即
132:  * 断链（短 TTL＋心跳续签的兑现形态）。assign 额外给被派方签发首张任务能力。
133:  * 任务不存在或离开在办持有态（交付/结算/关闭/取消/回收）不重签——下一张验签
134:  * 时即被投影吊销，签了也是死信。结论件附 `capability`（下一张信封）或
135:  * `capabilityError`（签发失败留痕——旧信封已被本命令消费，签发失败必须响亮）。
136:  *
137:  * **续签条件（21 号票 ①）＝授权有效且信封已被本命令消费**，不再是「命令成功」：
138:  * 「授权通过而命令被拒」的常态拒绝（cas-mismatch／illegal-transition 等，§D
139:  * 「不符即拒」）同样续签——旧信封已被那条命令单次消费，不续签即需 host 干预
140:  * 才能恢复。机械证据＝台账拒绝回执的 `authorized` 标记（鉴权门**之后**的拒绝
141:  * 才带）；鉴权门之前的拒绝（角色不符／鉴权失败／结构校验）不续签，越权尝试
142:  * 不得换来新信封。幂等重放（replayed）不重签：原命令的原信封消费史不重复。
143:  * 续签点＝**每个授权有效的 post 命令**（2026-09-19 用户裁定，21 号票 ④：§D
144:  * 「台账转移点」列举之外，实现口径以此为准；岗位 op 集口径见 op-set 头注）。
145:  */
146: export function createLedgerCommandDispatcher({ ledger, issuer, postForBot, logger } = {}) {
147:   if (!ledger || typeof ledger.command !== "function") {
148:     throw new Error("createLedgerCommandDispatcher 需要台账门面");
149:   }
150:   function reissueFor(botId, taskId, result) {
151:     const post = postForBot?.(botId) ?? null;
152:     if (post === null) {
153:       logger?.warn?.(`[dsh-bots] capability 签发跳过：${botId} 未绑定 home 岗位（${String(result.taskId)} 转移点）`);
154:       return result;
155:     }
156:     if (!OP_SET[post]?.some((op) => TASK_SCOPED_OPS.includes(op))) return result; // 无任务域 op 的岗位（如统筹）：无任务能力可签
157:     const issued = issuer.issueTaskCapability({ taskId, botId, post });
158:     if (!issued.ok) {
159:       logger?.warn?.(`[dsh-bots] capability 签发失败（${issued.code}）：${issued.reason}`);
160:       return { ...result, capabilityError: { code: issued.code, reason: issued.reason } };
161:     }
162:     return { ...result, capability: issued.envelope };
163:   }
164:   /** 任务当前状态（投影读）；任务不存在或台账不可读一律 undefined（fail closed：不续签）。 */
165:   function taskStatusOf(taskId) {
166:     if (typeof taskId !== "string" || taskId === "" || typeof ledger.task !== "function") return undefined;
167:     try {
168:       return ledger.task(taskId)?.status;
169:     } catch {
170:       return undefined;
171:     }
172:   }
173:   return async function dispatch(input = {}) {
174:     let result = await ledger.command(input);
175:     if (result.replayed === true) return result; // 幂等重放：原命令的原信封消费史不重复，不重签
176:     // 续签条件（21 号票 ①）：授权有效且信封已被本命令消费——成功命令照旧；
177:     // 授权通过而被拒的常态拒绝（台账拒绝回执带 authorized）同样续签，否则旧
178:     // 信封已消费而链断。鉴权门之前的拒绝不带该标记＝不续签（越权不换新信封）。
179:     if (result.ok === false && result.authorized !== true) return result;
180:     let roleCapability;
181:     if (input.actor?.kind === "post" && input.capability?.payload?.kind === "role") {
182:       const issued = issuer.issueRoleCapability({ botId: input.actor.id, post: postForBot?.(input.actor.id) });
183:       if (!issued.ok) return { ...result, capabilityError: { code: issued.code, reason: issued.reason } };
184:       roleCapability = issued.envelope;
185:     }
186:     // assign：给被派方签发首张任务能力（承接链的起点）
187:     if (result.ok === true && input.op === "task.assign") {
188:       const assignee = input.payload?.assignee ?? null;
189:       result = assignee === null ? result : reissueFor(assignee, result.taskId, result);
190:       return roleCapability ? { ...result, roleCapability } : result;
191:     }
192:     if (roleCapability) return { ...result, capability: roleCapability };
193:     // 其余（成功或授权通过而被拒）：给持有者本人续签下一张（链式——单次消费下
194:     // 不断链的唯一方式）。任务不存在或已离开在办态不签：签了也是死信。
195:     if (input.actor?.kind !== "post") return result;
196:     const taskId = input.taskId ?? result.taskId;
197:     const status = taskStatusOf(taskId);
198:     if (status === undefined || !ACTIVE_CAP_STATES.includes(status)) return result;
199:     return reissueFor(input.actor.id, taskId, result);
200:   };
201: }
