===== op-set.js (head) =====
1: /**
2:  * op-set 岗位表与工具面派生（org-v2 06 号票；规格 §D/§E 与附录 A `V-A3.3`／
3:  * `V-A3.4`／`V-A4.1`／`V-A4.9`）。
4:  *
5:  * op-set 表＝组织命令面的**岗位白名单唯一源**：每岗位可持有哪些 op 由本表封闭
6:  * 枚举，工具面由本表派生（一 op 一工具、工具名即 op 名——工具面裁剪＝权限裁剪）。
7:  * 规格域词到台账命令词的映射（§D op-set → lib/org/task-ledger.js OPS）：
8:  *   - `task.create`（立项）＝`task.plan`；`task.claim`＝`task.accept`；
9:  *     `brief.amend`＝`task.amend`；承接岗 `task.escalate`＝`task.wait-user`／
10:  *     `task.fail`（上浮由台账 `escalated` 事件承载，宿主 sweep 驱动）。
11:  *   - §D 岗位表未点名、而由 §B 责任表（STATE_RESPONSIBILITY「每态下一步谁负责」）
12:  *     推导给岗位的台账命令：项目经理持 `task.close`／`task.cancel`／`task.unblock`／
13:  *     `task.resume`／`task.requeue`（delivered/settled 态责任人与队列归位人）、
14:  *     值班统筹持 `task.exception`（值守维护职责）——§D 列举的是域级能力面，
15:  *     台账命令面更细，细化映射以本表为唯一源（对账以本表为准）。
16:  *     **2026-09-19 用户裁定（21 号票 ④）**：上列推导**升格为裁定口径**——岗位 op
17:  *     集以本表为唯一源，§D 列举的域级能力面不构成台账命令面的封闭枚举；同轮
18:  *     裁定续签点＝**每个授权有效的 post 命令**（§D「转移点」列举之外，实现口径
19:  *     以 `permissions.createLedgerCommandDispatcher` 头注为准）。
20:  *   - 复核帽的域 op（`artifact.read`／`evidence.read|probe`／`results.read`／
21:  *     `review.report`）与 `review.request`／`artifact.submit`／`evidence.read`／
22:  *     `routine.trigger` 尚无命令面实体——列 **RESERVED_OPS 保留集**（随归属票
23:  *     08/12 落地时升入可执行表），不得预混进 OP_SET（对账会把「登记了不可执行
24:  *     的 op」报为违例）；`evidence.probe` 已随 07 号票升入承接岗可执行表（执行
25:  *     面分类 EXECUTE_OPS）。
26:  * 读写分类（READ_OPS／WRITE_OPS）覆盖「命令面全词表 ∪ ledger.read ∪ 读面扩展
27:  * op」（读面扩展现＝brief.refresh，19 号票②），是 V-A3.4「复核帽不含任何写 op」
28:  * 机械检查的完备性前提：两类不交、并集封闭，新 op 进命令面时漏分类即被对账抓出。
29:  *
30:  * 动态工具面不变量（§E；`V-A1.4` 借用不变量）：实例任一时刻可用组织命令集＝
31:  * `availableOps(home, capability)`＝home 岗位 op 集 ∪ 当次签发 capability 的
32:  * op 集；帽卸或租约回收即失效（失效判定在 capability-issue 的验签面，与吊销
33:  * 联动同拍）。
34:  */
35: import { OPS } from "./task-ledger.js";
36: import { ROLE_CARDS } from "./role-cards.js";
37: 
38: /** 台账命令面全词表（task-ledger OPS 的键，冻结快照）。 */
39: export const LEDGER_COMMAND_OPS = Object.freeze([...Object.keys(OPS)]);
40: 
41: /** 读 op（读面，不落事件）。台账投影读＋复核移交件读（08 号票，复核帽专用面）
42:  *  ＋持有件刷新（19 号票②：brief.refresh——实例侧读台账投影重同步本地持有简报）。 */
43: export const READ_OPS = Object.freeze(["ledger.read", "artifact.read", "brief.refresh"]);
44: 
45: /**
46:  * 写 op（追加台账事件的一切命令——含 judgement/heartbeat/exception 这类非状态
47:  * 事实）。当前命令面每个 op 都落事件，故写集＝命令面全词表。
48:  */
49: export const WRITE_OPS = Object.freeze([...LEDGER_COMMAND_OPS]);
50: 
51: /**
52:  * 任务域 op：须持绑定 `binding.taskId` 的任务能力方可执行（承接执行集）。
53:  * 组织运营 op（intake/triage/plan/assign/settle 等）由 home 岗位 op 集（角色
54:  * 能力）覆盖，不在此列。`evidence.probe` 是执行面 op（非台账命令），但同样是
55:  * 任务域授权——探针针对某张任务的预登记判据执行，随任务吊销同拍。
56:  */
57: export const TASK_SCOPED_OPS = Object.freeze([
58:   "task.accept", "task.decline", "task.start", "task.report", "task.deliver", "task.heartbeat",
59:   "task.judge", "task.block", "task.wait-user", "task.fail", "evidence.probe"
60: ]);
61: 
62: /**
63:  * 执行面 op（07 号票升表 evidence.probe；08 号票升表 review.report；10 号票升表
64:  * knowledge.register；11 号票升表 mail.send）：**非台账命令**——经 host 侧对应面
65:  * 执行（探针白名单 `lib/org/probe.js`；复核报告经台账 `recordReviewReport` 落盘；
66:  * 知识登记经 `lib/knowledge.js registerReport` 在 **host 进程内**执行；邮件投递经
67:  * `lib/org/mail-relay.js` 在 **host 进程内**落盘——bot 侧零直写，`V-A4.4`），
68:  * 不作为台账命令落事件。与读写两类互斥：WRITE_OPS＝「追加台账事件的一切命令」，
69:  * 执行面 op 本体不落事件故不属写集。
70:  *
71:  * `mail.send` 是本表唯一的**零门槛**执行面 op：规格 §E「全员基础工具＝mail.send＋
72:  * …」——它对 bot 无 capability 门槛（`V-A3.7` 邮件零权威、投递保持低摩擦），因此
73:  * 不进 TASK_SCOPED_OPS，四个常设岗各持一份；复核帽按 `V-A3.4` 不持（它是共享面
74:  * 写者，见 MUTATING_OPS）。「全员」＝全员**岗位**（复核是帽不是岗），与
75:  * `knowledge.register` 的读-写划分同口径。
76:  */
77: export const EXECUTE_OPS = Object.freeze([
78:   "evidence.probe", "review.report", "knowledge.register", "knowledge.deprecate", "mail.send"
79: ]);
80: 
81: /**
82:  * 变异 op 集＝**改共享面或台账的一切 op**：WRITE_OPS（落台账事件）∪ 执行面里的
83:  * 共享面写者（`knowledge.register`／`mail.send`——后者写的是各实例邮箱目录）。
84:  * 这是 `V-A3.4`「复核帽不含任何写 op」的本义——台账事件写者与共享面写者都是
85:  * 变异，复核帽两类都不得持（只看 WRITE_OPS 会漏掉「不落事件但改共享面」的通道）。
86:  */
87: export const MUTATING_OPS = Object.freeze([
88:   ...WRITE_OPS, "knowledge.register", "knowledge.deprecate", "mail.send"
89: ]);
90: /**
91:  * `review.report` **不在**变异集（看似违反上句的「一切 op」）：它是复核帽**本职**
92:  * 的读后写动作（复核者的产出就是报告），把它计入变异集等于让复核帽无法履责
93:  * （`V-A3.3` 要求复核帽持 `review.report`）。本集的判定用途是「复核帽不得持」，
94:  * 故口径＝**复核帽不该持有的共享面/台账写者**，而非字面的「所有会写盘的 op」。
95:  */
96: 
97: /**
98:  * op-set 岗位表（可执行面）。复核帽可执行集（08 号票升表）：`artifact.read`
99:  * （移交件读）＋`evidence.probe`（判据探针）＋`review.report`（报告提交）——
100:  * 读面∪执行面、**零写 op、无 ledger.read**（`V-A3.3`／`V-A3.4` 由 validateOpSet
101:  * 与保留集双向机械把守，不靠约定）。`review.request`（复核请求）随 08 升入
102:  * project-lead 行（台账命令、落事件，属管理类写集）。
103:  */
104: /**
105:  * 承接岗共享表：researcher/implementer 同为承接执行岗（执行集＋台账读；保留集
106:  * 同口径），共享同一冻结件——升表时一处改、两岗同步。
107:  */
108: const DELIVERY_POST_OPS = Object.freeze([
109:   "task.accept", "task.decline", "task.start", "task.report", "task.deliver", "task.heartbeat",
110:   "task.judge", "task.block", "task.wait-user", "task.fail", "evidence.probe", "brief.refresh",
111:   "knowledge.register", "knowledge.deprecate", "mail.send", "ledger.read"
112: ]);
113: const DELIVERY_RESERVED_OPS = Object.freeze(["artifact.submit", "artifact.read", "evidence.read"]);
114: 
115: export const OP_SET = Object.freeze({
116:   "duty-coordinator": Object.freeze([
117:     "task.intake", "task.triage", "task.exception",
118:     "knowledge.register", "knowledge.deprecate", "mail.send", "ledger.read"
119:   ]),
120:   "project-lead": Object.freeze([
121:     "task.plan", "task.assign", "task.amend", "task.settle",
122:     "task.close", "task.cancel", "task.unblock", "task.resume", "task.requeue",
123:     "review.request", "knowledge.register", "knowledge.deprecate", "mail.send", "ledger.read"
124:   ]),
125:   "researcher": DELIVERY_POST_OPS,
126:   "implementer": DELIVERY_POST_OPS,
127:   "verifier": Object.freeze(["artifact.read", "evidence.probe", "review.report"])
128: });
129: 
130: /**
===== capability-issue.js (178) =====
1: /**
2:  * capability 签发与验签面（org-v2 06 号票；规格 §D 与附录 A `V-A3.5`、`V-A3.3`、
3:  * `V-A1.4`）。
4:  *
5:  * **签发权在 host**：信封由本模块（host 侧）HMAC 签发，bot 只能持信封调命令、
6:  * 不能自请自签——本模块不提供任何「按 bot 请求出信封」的入口，签发点由接线层
7:  * 挂在台账转移结果上（assign→任务能力；此后每个授权有效且信封已消费的 post
8:  * 命令→续签重签，21 号票 ①）。递送只经认证 host 命令通道（命令返回件携带），
9:  * **不经 mail**（`V-A3.7` 结构前提）。
10:  *
11:  * 信封＝{payload, sig}（capability-base 冻结原语）；payload＝{v, kind, jti, botId,
12:  * post, taskId, ops, nonce, iat, exp, gen}：
13:  *   - **单次消费**：nonce 经 consumeNonceOnce 独占落盘（重放即拒）；
14:  *   - **短 TTL**：exp 由可注入 ttlMs 决定（长任务＝心跳续签：续签＝按当前投影
15:  *     重签新 jti，旧信封已被消费自然作废）；
16:  *   - **任务域绑定**：kind=task 的信封绑定 taskId；kind=role 的信封 taskId 为空、
17:  *     只携组织运营 op，**不得充当任务域授权**（`V-A1.4` 借用不变量的签发侧）；
18:  *   - **代际绑定＋活态**：gen＝签发时的实例注册表行 hostInstanceId，验签比对最新
19:  *     行并要求 pid 活态（capability-base 冻结语义，fail closed）；
20:  *   - **自动吊销＝投影判定**：任务能力验签时实时折叠台账投影——owner 非持有者
21:  *     或状态离开在办集（租约回收/重派/上浮/交付/取消/关闭）即 `capability-revoked`，
22:  *     不依赖显式吊销动作、无吊销窗口。
23:  *
24:  * op 集纪律（`V-A3.3` 对账的签发侧）：可签 op ⊆ op-set 表对应岗位（越表/保留
25:  * op/空集一律 fail closed）；复核帽只按 verifier 行签发。
26:  */
27: import { randomBytes } from "node:crypto";
28: import { join } from "node:path";
29: 
30: import {
31:   consumeNonceOnce, currentInstanceRow, isCapabilityEnvelope,
32:   nextCapabilityNonce, pidAlive, readOrCreateSecret, signCapabilityPayload,
33:   verifyCapabilitySignature
34: } from "./capability-base.js";
35: import { appendJsonlLine } from "./store-base.js";
36: import { HOLDING_STATES, isTaskId } from "./task-ledger.js";
37: import { TASK_SCOPED_OPS, tableOpsForKind } from "./op-set.js";
38: 
39: /** capability 数据域根：`<dshHome>/bots/capabilities`（锁域与台账互不嵌套）。 */
40: export function capabilityDir(dshHome) {
41:   return join(dshHome, "bots", "capabilities");
42: }
43: function secretFileFor(dshHome) {
44:   return join(capabilityDir(dshHome), "secret");
45: }
46: function nonceDirFor(dshHome) {
47:   return join(capabilityDir(dshHome), "nonces");
48: }
49: export function issuedAuditFile(dshHome) {
50:   return join(capabilityDir(dshHome), "issued.jsonl");
51: }
52: 
53: /** 默认短 TTL（数值属用户域的缝：接线可逐项覆盖；对齐派单租约量级）。 */
54: export const CAPABILITY_TTL_MS = 15 * 60 * 1000;
55: 
56: /** 任务能力仍有效的状态集（在办持有着）；离开即吊销（交付/取消/关闭/回收…）。 */
57: export const ACTIVE_CAP_STATES = Object.freeze([
58:   ...HOLDING_STATES, "blocked", "waiting-user", "failed"
59: ]);
60: 
61: /**
62:  * 建 capability 签发/验签门面。`ledger`＝任务台账门面（投影吊销判定用；构造
63:  * 顺序不便时可后补 `bindLedger()`——接线必须最终绑定真台账，否则任务能力的
64:  * 吊销腿退化为绑定相等性检查，仅限纯单测场景）。
65:  */
66: export function createCapabilityIssuer({ dshHome, ledger, now = () => Date.now(), ttlMs = CAPABILITY_TTL_MS } = {}) {
67:   if (typeof dshHome !== "string" || dshHome === "") throw new Error("createCapabilityIssuer 需要 dshHome");
68:   if (!(Number.isInteger(ttlMs) && ttlMs > 0)) throw new Error("ttlMs 须为正整数（短 TTL 缝）");
69:   let ledgerRef = ledger;
70: 
71:   function fail(code, reason) {
72:     return { ok: false, code, reason };
73:   }
74: 
75:   const domainMismatch = (payload, taskId) =>
76:     fail("task-domain-mismatch", `能力绑定 ${String(payload.taskId)}，不得用于 ${String(taskId)}`);
77: 
78:   function issue({ botId, post, kind = "role", taskId = null, ops } = {}) {
79:     if (typeof botId !== "string" || botId === "") return fail("issue-invalid", "botId 必填");
80:     const allowed = tableOpsForKind(post, kind);
81:     if (allowed.length === 0) {
82:       return fail("issue-op-set", `岗位 ${String(post)} 在 op-set 表下无可签 ${kind === "task" ? "任务" : "角色"} op（fail closed）`);
83:     }
84:     const requested = ops ?? allowed;
85:     for (const op of requested) {
86:       if (!allowed.includes(op)) {
87:         return fail("issue-op-set", `签发 op ${op} 越出岗位表（${post}/${kind}）——对账 fail closed`);
88:       }
89:     }
90:     if (kind === "task") {
91:       if (!isTaskId(taskId)) return fail("issue-invalid", `任务能力须绑合法 taskId：${String(taskId)}`);
92:     } else if (taskId !== null && taskId !== undefined) {
93:       return fail("issue-invalid", "角色能力不得绑定 taskId");
94:     }
95:     const row = currentInstanceRow(dshHome, botId);
96:     if (!row.ok) return fail("instance-unknown", row.reason);
97:     const iat = now();
98:     const payload = {
99:       v: 1,
100:       kind,
101:       jti: randomBytes(8).toString("hex"),
102:       botId,
103:       post,
104:       taskId: taskId ?? null,
105:       ops: [...requested],
106:       nonce: nextCapabilityNonce(),
107:       iat,
108:       exp: iat + ttlMs,
109:       gen: row.row.hostInstanceId
110:     };
111:     const sig = signCapabilityPayload(readOrCreateSecret(secretFileFor(dshHome)), payload);
112:     appendJsonlLine(issuedAuditFile(dshHome), {
113:       at: new Date(iat).toISOString(), jti: payload.jti, kind, botId, post, taskId: payload.taskId, ops: payload.ops, exp: payload.exp
114:     });
115:     return { ok: true, envelope: { payload, sig }, payload };
116:   }
117: 
118:   /**
119:    * 验签（三元组的「实例活态」腿＋任务域绑定/吊销腿；op 白名单腿在鉴权面——
120:    * 它需要 home 岗位）。校验序纪律：过期先于 nonce（capability-base 冻结口径），
121:    * 失败一律不消费 nonce（除 nonce 腿本身）。
122:    */
123:   function verify({ envelope, botId, taskId, op, consumeNonce = true } = {}) {
124:     if (!isCapabilityEnvelope(envelope)) return fail("capability-malformed", "信封须为 {payload, sig}");
125:     if (!verifyCapabilitySignature(readOrCreateSecret(secretFileFor(dshHome)), envelope)) {
126:       return fail("capability-signature", "信封签名不符（非 host 签发或被篡改）");
127:     }
128:     const payload = envelope.payload;
129:     if (payload.botId !== botId) return fail("capability-bot-mismatch", `信封属 ${String(payload.botId)}，不得为 ${String(botId)} 所用`);
130:     if (!(Number.isFinite(payload.exp) && now() < payload.exp)) {
131:       return fail("capability-expired", "能力已过短 TTL（须心跳续签）");
132:     }
133:     const row = currentInstanceRow(dshHome, botId);
134:     if (!row.ok || row.row.hostInstanceId !== payload.gen) {
135:       return fail("capability-generation", "实例代际已轮换或注册表不可读（fail closed）");
136:     }
137:     if (!pidAlive(row.row.pid)) return fail("instance-not-alive", "实例注册表最新行 pid 已死（活态槽比对失败）");
138:     if (consumeNonce !== false && !consumeNonceOnce(nonceDirFor(dshHome), { nonce: payload.nonce, jti: payload.jti, botId })) {
139:       return fail("capability-replayed", "nonce 已消费（单次消费）");
140:     }
141:     const taskScoped = typeof op === "string" && TASK_SCOPED_OPS.includes(op);
142:     if (taskScoped) {
143:       if (payload.kind !== "task" || payload.taskId === null) {
144:         return fail("capability-task-scope", "任务域 op 须持绑定 taskId 的任务能力（角色能力不足）");
145:       }
146:       if (payload.taskId !== taskId) return domainMismatch(payload, taskId);
147:       if (ledgerRef) {
148:         let task;
149:         try {
150:           task = ledgerRef.task(payload.taskId);
151:         } catch (error) {
152:           return fail("ledger-corrupt", error.message);
153:         }
154:         if (task === null || !ACTIVE_CAP_STATES.includes(task.status) || task.owner !== botId) {
155:           return fail("capability-revoked", "任务已离开在办持有态（租约回收/交付/取消/关闭——自动吊销）");
156:         }
157:       }
158:     } else if (payload.kind === "task" && taskId !== undefined && taskId !== null && payload.taskId !== taskId) {
