191: export const PROBE_COMMANDS = Object.freeze([
192:   {
193:     name: "fs.contains",
194:     description: "dshHome 相对坐标的文件内容须含指定文本（只读检查）",
195:     argKeys: ["location", "text"],
196:     run(args, ctx) {
197:       // 33 号票 A6：参数值合法性在执行期判（冻结期只验键集，见 brief.js）——
198:       // 非串 location 会让 isAbsolute 同步抛 ERR_INVALID_ARG_TYPE 穿透，须先守卫。
199:       if (typeof args.location !== "string" || typeof args.text !== "string") {
200:         return { ok: false, code: "probe-args", reason: `location 与 text 须为字符串（fail closed）：${safeArgsText(args)}` };
201:       }
202:       const root = resolve(ctx.dshHome);
203:       if (isAbsolute(args.location)) {
204:         return { ok: false, code: "probe-path", reason: `location 须为 dshHome 相对坐标：${String(args.location)}` };
205:       }
206:       const target = resolve(root, args.location);
207:       const rel = relative(root, target);
208:       if (rel === "" || rel === ".." || rel.startsWith(`..${sep}`)) {
209:         return { ok: false, code: "probe-path", reason: `location 越出 dshHome：${String(args.location)}` };
210:       }
211:       let bytes;
212:       try {
213:         bytes = readFileSync(target);
214:       } catch (error) {
215:         return { ok: false, code: "probe-read", reason: `坐标不可读：${error.message}` };
216:       }
217:       const snapshot = bytesSnapshot({ location: String(args.location) }, bytes);
218:       const text = bytes.toString("utf8");
219:       return text.includes(args.text)
220:         ? { ok: true, output: `命中（${String(args.location)}）`, snapshot }
221:         : { ok: false, code: "probe-mismatch", reason: `文件 ${String(args.location)} 未含指定文本`, snapshot };
222:     }
223:   },
224:   {
225:     name: "node.tests",
226:     description: "仓库根 tests/ 下单个测试文件经隔离子进程执行，退出码 0 且无 SKIP 标记即过（33 号票 A5：跳过≠通过）",
227:     argKeys: ["file"],
228:     run(args, ctx) {
229:       // 33 号票 A6：file 非串时正则 test 会隐式强转——先守卫，归 probe-args。
230:       if (typeof args.file !== "string") {
231:         return { ok: false, code: "probe-args", reason: `file 须为字符串（fail closed）：${safeArgsText(args)}` };
232:       }
233:       if (!/^[A-Za-z0-9._-]+\.test\.mjs$/.test(args.file)) {
234:         return { ok: false, code: "probe-path", reason: `file 须为 tests/ 下单文件名：${String(args.file)}` };
235:       }
236:       const cwd = resolve(ctx.cwd ?? process.cwd());
237:       const target = join(cwd, "tests", args.file);
238:       let bytes;
239:       try {
240:         bytes = readFileSync(target);
241:       } catch (error) {
242:         return { ok: false, code: "probe-read", reason: `测试文件快照不可读（fail closed）：${error.message}` };
243:       }
244:       const fileSnapshot = bytesSnapshot({ file: String(args.file) }, bytes);
245:       const timeoutMs = Number.isInteger(ctx.timeoutMs) && ctx.timeoutMs > 0 ? ctx.timeoutMs : PROBE_TIMEOUT_MS;
246:       // 字面快照执行（24 号票②）：整树物化快照副本后，隔离子进程以副本根为 cwd
247:       // 执行——执行字节＝快照字节由构造保证（活树 ABA 窗口消除）。
248:       // 物化基座与子进程环境服从**同一解析链**（33 号票 B4＋复审 Spec(c)3）：
249:       // `ctx.tmpdir` 优先，否则 `TMPDIR → TEMP → TMP`，全缺用 `os.tmpdir()`；
