389: /**
390:  * args 键集与白名单命令的 argKeys 精确一致（多键少键都否）——简报冻结期校验
391:  * （lib/org/brief.js）与执行期校验（runCriterion）**同口径**的共用判定原语，
392:  * 免两处各自实现可漂移；调用方先各自保证 args 为对象。
393:  */
394: export function argsMatchArgKeys(args, command) {
395:   const keys = Object.keys(args).sort();
396:   const expected = [...command.argKeys].sort();
397:   return keys.length === expected.length && keys.every((key, index) => key === expected[index]);
398: }
