400: /**
401:  * 判据的逐字一致口径：两条判据 canonical JSON 相等即「逐字同一」——执行形态
402:  * 由登记形态唯一决定的机械判定（v1 沙箱探针同型）。
403:  */
404: export function criterionMatches(a, b) {
405:   return canonicalJson(a) === canonicalJson(b);
406: }
407: 
408: /**
409:  * 执行一条登记判据。fail closed：命令须在白名单内、参数键须与登记形态精确
410:  * 一致（多键少键都拒）；执行体结论只两态，**执行过的结论携带 snapshot 引用其
411:  * 所核验的快照**（键封闭形状见模块头注）。ctx＝{dshHome, cwd?, timeoutMs?,
412:  * tmpdir?, listMailAnomalies?}——dshHome 必填；`listMailAnomalies` 可注入
413:  * （缺省用投递面本体，测试注入假读面）；`tmpdir` 为字符串非空才认，否则按
414:  * `TMPDIR → TEMP → TMP` 回退（33 号票 B4 Windows 口径），生产接线不传。
415:  * 参数值合法性在执行期判（33 号票 A6：值非法一律 {ok:false} `probe-args`），
416:  * 执行体同步抛折 `probe-error`（不再穿透）。
417:  *
418:  * 结论顶层一律补 `snapshotSha256`（25 号票）：有快照＝该快照的字节级绑定
419:  * （`node.tests` 取树级摘要、其余取 sha256），采集未发生的拒绝＝`null`。
420:  * 消费方（关闭前置的通过记录）不必自解各命令的快照键形状即可复验／转述摘要；
421:  * **不改**结论的两态与 `snapshot` 形状（沙箱快照纪律不变，22／24 号票）。
422:  */
423: export async function runCriterion(criterion, ctx = {}) {
424:   if (typeof ctx.dshHome !== "string" || ctx.dshHome === "") {
425:     return { ok: false, code: "probe-ctx", reason: "runCriterion 需要 dshHome", snapshotSha256: null };
426:   }
427:   if (criterion === null || typeof criterion !== "object" || Array.isArray(criterion)) {
428:     return { ok: false, code: "probe-criterion", reason: "判据须为 {probe, args} 对象", snapshotSha256: null };
429:   }
430:   const command = probeCommand(criterion.probe);
431:   if (command === null) {
432:     return { ok: false, code: "probe-whitelist", reason: `判据命令不在白名单（fail closed）：${String(criterion.probe)}`, snapshotSha256: null };
433:   }
434:   const args = criterion.args ?? {};
435:   if (args === null || typeof args !== "object" || Array.isArray(args)) {
436:     return { ok: false, code: "probe-args", reason: "判据 args 须为对象", snapshotSha256: null };
437:   }
438:   if (!argsMatchArgKeys(args, command)) {
439:     return { ok: false, code: "probe-args", reason: `判据参数须恰为 {${command.argKeys.join(", ")}}（逐字一致）`, snapshotSha256: null };
440:   }
441:   const runCtx = {
442:     ...ctx,
443:     listMailAnomalies: ctx.listMailAnomalies ?? defaultListMailAnomalies
444:   };
445:   // 33 号票 A6：执行体同步抛（resolve 非串 cwd／isAbsolute 非串／快照外漏网之鱼）
446:   // 不得穿透——折成 {ok:false}（probe-error），与「跑不了不等于过了」同口径。
447:   let verdict;
448:   try {
449:     verdict = await command.run(args, runCtx);
450:   } catch (error) {
451:     return { ok: false, code: "probe-error", reason: `探针执行抛错（fail closed）：${error?.message ?? String(error)}`, snapshotSha256: null };
452:   }
453:   return { ...verdict, snapshotSha256: snapshotDigestOf(verdict) };
454: }
455: 
456: /**
457:  * 结论快照摘要（25 号票）：`node.tests` 的树级摘要优先（被执行的是整树副本），
458:  * 其余命令取坐标级 sha256；无快照（采集未发生的拒绝）＝null。
459:  */
460: function snapshotDigestOf(verdict) {
461:   const snapshot = verdict?.snapshot;
462:   if (snapshot === null || snapshot === undefined) return null;
463:   if (typeof snapshot.tree === "string") return snapshot.tree;
464:   if (typeof snapshot.sha256 === "string") return snapshot.sha256;
465:   return null;
466: }
