1: /** 16 号票只读切换检查。代码清单由目录派生；授权、备份、smoke 各自另有执行凭据。 */
2: import { readFileSync } from "node:fs";
3: import { join } from "node:path";
4: import { cutoverRoster, readyChannels, readinessProbe, READINESS_SCHEMA } from "./cutover-readiness.js";
5: import { deploymentInventory } from "./deployment-inventory.js";
6: import { runAcceptanceSync } from "../../scripts/acceptance-coordinates-sync.mjs";
7: export { deploymentInventory } from "./deployment-inventory.js";
8: 
9: export async function checkCutover({ repoRoot, dshHome, hostUrl = null }) {
10:   const registry = JSON.parse(readFileSync(join(dshHome, "bots", "bots.json"), "utf8"));
11:   if (!registry || Array.isArray(registry) || typeof registry !== "object") throw new Error("注册表须为对象");
12:   const roster = cutoverRoster(registry);
13:   const deployment = deploymentInventory(repoRoot, join(dshHome, "plugins", "dsh-bots"));
14:   const coordinates = runAcceptanceSync({ repoRoot });
15:   let runtime = { ok: false, reason: "未指定 --host-url，运行态未核验" };
16:   if (hostUrl !== null) {
17:     try {
18:       const response = await fetch(new URL("/api/bots/_ledger/readiness", hostUrl), { signal: AbortSignal.timeout(5000) });
19:       const data = await response.json();
20:       const age = Date.now() - Date.parse(data?.capturedAt);
21:       const channelsReady = readyChannels(registry, data?.channels, deployment.sourceDigest);
22:       const probe = readinessProbe({ checkedAt: data?.probe?.checkedAt,
23:         report: { face: "deploy", ...data?.probe, gatePass: data?.probe?.ok === true } }, Date.now());
24:       runtime = { ...data, ok: response.ok && data.schema === READINESS_SCHEMA
25:         && data.ok === true && data.sourceDigest === deployment.sourceDigest
26:         && data.roster?.ok === true && age >= -5000 && age <= 30_000 && channelsReady && probe.ok };
27:       if (data.sourceDigest !== deployment.sourceDigest) runtime.reason = "宿主加载的代码摘要与仓库不符，须完成重启链";
28:     } catch (error) { runtime = { ok: false, reason: String(error.message) }; }
29:   }
30:   return { capturedAt: new Date().toISOString(), scope: "readiness-only",
31:     ready: roster.ok && deployment.ok && coordinates.ok && runtime.ok,
32:     roster, deployment, coordinates, runtime };
33: }
