1: /** Read-only runtime readiness, independent of authorization, preflight and real smoke evidence. */
2: import { minimalRosterState } from "./role-cards.js";
3: import { validateHostContractReport } from "./host-contract.js";
4: import { isNonEmptyString } from "./is-non-empty-string.js";
5: 
6: export const READINESS_SCHEMA = "org-v2/cutover-readiness@1";
7: // 就绪要求十一分钟内的观测，与宿主调度窗的可配置性分开。
8: const PROBE_MAX_AGE_MS = 11 * 60 * 1000;
9: 
10: export function readyChannels(registry, channels, sourceDigest) {
11:   return Array.isArray(channels) && channels.length === 2
12:     && Object.keys(registry).every((botId) => channels.some((row) => row.botId === botId
13:       && row.connected === true && row.delivered === true && row.roleReady === true
14:       && typeof row.gen === "string" && row.gen !== "" && row.sourceDigest === sourceDigest));
15: }
16: 
17: export function readinessProbe(observation, at) {
18:   if (!observation) return { ok: false, reason: "宿主 deploy 探针尚无结果" };
19:   try {
20:     const report = validateHostContractReport(observation.report);
21:     const age = at - observation.checkedAt;
22:     return { ok: report.gatePass && age >= 0 && age <= PROBE_MAX_AGE_MS,
23:       checkedAt: observation.checkedAt, counts: report.counts, results: report.results };
24:   } catch (error) { return { ok: false, reason: error.message }; }
25: }
26: 
27: export function cutoverRoster(registry) {
28:   const state = minimalRosterState(registry);
29:   const seats = Object.entries(registry);
30:   const invalidSeats = seats.filter(([id, seat]) => seat?.id !== id
31:     || !["duty-coordinator", "implementer"].includes(seat.post)).map(([id]) => id);
32:   const anchors = seats.filter(([, seat]) => seat?.bootstrapAnchor === true);
33:   const unconfiguredSeats = seats.filter(([, seat]) => !isNonEmptyString(seat?.modelProvider)
34:     || !isNonEmptyString(seat?.model) || !isNonEmptyString(seat?.permission)).map(([id]) => id);
35:   return { ...state, invalidSeats, unconfiguredSeats,
36:     ok: seats.length === 2 && state.minimalComplete && invalidSeats.length === 0
37:       && unconfiguredSeats.length === 0 && anchors.length === 1 && anchors[0][1].post === "duty-coordinator" };
38: }
39: 
40: export function createCutoverReadiness({ host, readRegistry, sourceDigest } = {}) {
41:   return () => {
42:     const at = host.now();
43:     const registry = readRegistry();
44:     const roster = cutoverRoster(registry);
45:     const channels = host.delivery?.status() ?? [];
46:     const probe = readinessProbe(host.probeStatus(), at);
47:     return { schema: READINESS_SCHEMA, capturedAt: new Date(at).toISOString(), sourceDigest,
48:       ok: /^[a-f0-9]{64}$/.test(sourceDigest ?? "") && roster.ok
49:         && readyChannels(registry, channels, sourceDigest) && probe.ok,
50:       roster, channels, probe };
51:   };
52: }
