28: /**
29:  * 顺序自启动（后台执行体）。返回 {started, already, failed, disabled} 供测试
30:  * 与日志断言；gapMs/sleep 可注入以便测试零等待。
31:  */
32: export async function autoStartBots(ctx, api, {
33:   gapMs = 1500,
34:   sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
35:   isAlive = null
36: } = {}) {
37:   const result = { started: [], already: [], failed: [], disabled: false };
38:   if (process.env.DSH_BOTS_AUTOSTART === "0") {
39:     result.disabled = true;
40:     ctx.logger?.info?.("[dsh-bots] bot 自启动已被 DSH_BOTS_AUTOSTART=0 关闭");
41:     return result;
42:   }
43:   const registry = api.readRegistry();
44:   const alive = isAlive ?? ((pid) => {
45:     try { process.kill(pid, 0); return true; } catch (error) { return error.code === "EPERM"; }
46:   });
47:   const ids = selectBotsToAutoStart(registry, alive);
48:   if (ids.length > 0) {
49:     ctx.logger?.info?.(`[dsh-bots] 宿主启动：跟随自启动 ${ids.length} 个 bot（${ids.join("、")}）`);
50:   }
51:   for (const id of ids) {
52:     try {
53:       const outcome = await api.start(id);
54:       if (outcome?.alreadyRunning) {
55:         result.already.push(id);
56:       } else {
57:         result.started.push(id);
58:         ctx.logger?.info?.(`[dsh-bots] 自启动 ${id}：pid=${outcome?.pid}`);
59:       }
60:     } catch (error) {
61:       result.failed.push(id);
62:       ctx.logger?.warn?.(`[dsh-bots] 自启动 ${id} 失败（不中断其余）：${error?.message ?? error}`);
63:     }
64:     if (gapMs > 0) await sleep(gapMs);
65:   }
66:   return result;
67: }
