21: const ENV_NAME_DENY_RE = /KEY|TOKEN|SECRET|PASSWORD/i;
22: /** 一律不透传的精确名（注入向量：child node 可被宿主 NODE_OPTIONS 预载）。 */
23: const ENV_NAME_DENY_EXACT = new Set(["NODE_OPTIONS"]);
