29:  * 减去拒绝形状，再叠加 overrides（调用方 DSH 显式集，最高优先）。
30:  * source 里存在但不在上述集合的变量一律不进入产物。
31:  * overrides 只取「名称形状」过滤（值是调用方显式给出、不查 source 存在性），
32:  * 拒绝形状对 overrides 同样生效——spec 的「一律不含」不分来源。
33:  */
34: export function buildSpawnEnv(source, overrides = {}) {
35:   const env = {};
36:   const allowedName = (name) =>
37:     typeof name === "string" && name !== ""
38:     && !ENV_NAME_DENY_EXACT.has(name) && !ENV_NAME_DENY_RE.test(name);
39:   const pick = (name) => {
40:     if (!allowedName(name)) return;
41:     const value = source[name];
42:     if (value === undefined) return;
43:     env[name] = value;
44:   };
45:   for (const name of BASE_ENV_NAMES) pick(name);
46:   for (const name of Object.keys(source)) {
47:     if (BASE_ENV_PREFIXES.some((prefix) => name.startsWith(prefix))) pick(name);
48:   }
49:   const extra = source[ENV_EXTRA_VAR];
50:   if (typeof extra === "string" && extra !== "") {
51:     for (const raw of extra.split(",")) pick(raw.trim());
52:   }
53:   for (const [name, value] of Object.entries(overrides)) {
54:     if (!allowedName(name) || value === undefined) continue;
55:     env[name] = value;
56:   }
57:   return env;
58: }

