1	/**
2	 * bot 文件面权限收紧（B4-02：环境与文件边界，2026-09-07）。
3	 * 目标形态：profile/workspace **顶层目录** 0700、敏感文件（package.json/
4	 * cordis.patch.yml/settings.yaml/pnpm-workspace.yaml）与注册表 bots.json
5	 * 0600——同机其他用户既被目录遍历位挡住，文件位也是第二道防线。
6	 * 只收紧**顶层目录与具名文件**，不递归 bot 树（node_modules 的 .bin 需要
7	 * 执行位，递归 0600 会打断 pnpm）；符号链接一律跳过（lstat 判别，不追改
8	 * 链接目标）；全部幂等，重复执行无副作用。
9	 */
10	import { chmodSync, lstatSync } from "node:fs";
11	import { join } from "node:path";
12	
13	export const TIGHT_DIR_MODE = 0o700;
14	export const TIGHT_FILE_MODE = 0o600;
15	
16	/** profile 内需要收紧的具名文件（settings.yaml 含模型凭据，其余统一收紧不逐件辩论）。 */
17	const TIGHT_PROFILE_FILES = ["package.json", "cordis.patch.yml", "settings.yaml", "pnpm-workspace.yaml"];
18	
19	/**
20	 * 幂等收紧单一路径：目录→0700、常规文件→0600；符号链接与特殊文件跳过；
21	 * 不存在/失败返回 false（收紧尽力而为，不阻塞主流程）。
22	 */
23	export function tightenPath(target, { dirMode = TIGHT_DIR_MODE, fileMode = TIGHT_FILE_MODE } = {}) {
24	  let st;
25	  try {
26	    st = lstatSync(target);
27	  } catch {
28	    return false;
29	  }
30	  if (st.isSymbolicLink()) return false;
31	  const targetMode = st.isDirectory() ? dirMode : st.isFile() ? fileMode : null;
32	  if (targetMode === null) return false;
33	  // 已达标即短路：Linux 上同 mode 的 chmod 仍推 ctime，重复执行就不再是零副作用
34	  //（比较 0o7777 全位——setuid 等特殊位在位时不短路，仍由 chmod 归零）。
35	  if ((st.mode & 0o7777) === (targetMode & 0o7777)) return true;
36	  try {
37	    chmodSync(target, targetMode);
38	  } catch {
39	    return false;
40	  }
41	  return true;
42	}
43	
44	/**
45	 * 幂等收紧一个 bot 的文件面（scaffold/startup 路径调用）：顶层目录 ×2 ＋
46	 * 具名文件 ×4。存量旧权限（0644 等）在下次 start/宿主启动时被收回。
47	 */
48	export function tightenBotTree(profileDir, workspaceDir) {
49	  tightenPath(profileDir);
50	  tightenPath(workspaceDir);
51	  for (const name of TIGHT_PROFILE_FILES) {
52	    tightenPath(join(profileDir, name));
53	  }
54	} 
