```js
/**
 * 统一文件 IO 门 —— lib/safe-io.js。
 *
 * 目的：收拢 lib/ 下对 node:fs 常用读写原语的**直调**——读（readFileSync）、
 * 写（writeFileSync／appendFileSync）、目录（mkdirSync／readdirSync／rmSync／
 * cpSync）、查询（existsSync／statSync）九个同步原语一律经由本门转发；
 * 其余原语（open/close/fsync/write/read/rename/lstat/realpath/mkdtemp/
 * chmod 等）仍直连 node:fs，不在本门范围。
 *
 * 形态：逐原语的**薄封装**——同名同参透传，函数内部恰为一次 node:fs 转发，
 * 不做任何额外加工（不加默认参数、不改返回值、不吞异常），因此对调用方
 * 行为与直调 node:fs 完全一致；后续若需在读写面上加统一策略（审计、权限、
 * 计量），改这里一处即可覆盖全部调用点。
 *
 * 加载：本文件为 ESM，lib/ 下 ESM 模块直接 import；lib/shared.cjs 经
 * require(ESM)（Node ≥ 22.12）加载同一份实现，保证 CJS/ESM 两侧同一道门。
 */
import {
  appendFileSync as fsAppendFileSync,
  cpSync as fsCpSync,
  existsSync as fsExistsSync,
  mkdirSync as fsMkdirSync,
  readFileSync as fsReadFileSync,
  readdirSync as fsReaddirSync,
  rmSync as fsRmSync,
  statSync as fsStatSync,
  writeFileSync as fsWriteFileSync
} from "node:fs";

/** 读文件（同 node:fs.readFileSync：无 options 返回 Buffer，给编码返回 string）。 */
export function readFileSync(...args) {
  return fsReadFileSync(...args);
}

/** 写文件（同 node:fs.writeFileSync：截断写入，原子性由调用方的 tmp+rename 负责）。 */
export function writeFileSync(...args) {
  return fsWriteFileSync(...args);
}

/** 追加写（同 node:fs.appendFileSync）。 */
export function appendFileSync(...args) {
  return fsAppendFileSync(...args);
}

/** 建目录（同 node:fs.mkdirSync：recursive 由其 options 决定）。 */
export function mkdirSync(...args) {
  return fsMkdirSync(...args);
}

/** 列目录（同 node:fs.readdirSync）。 */
export function readdirSync(...args) {
  return fsReaddirSync(...args);
}

/** 取元数据（同 node:fs.statSync：跟随符号链接，不存在的路径照常 throw）。 */
export function statSync(...args) {
  return fsStatSync(...args);
}

/** 存在性（同 node:fs.existsSync：布尔返回，不抛）。 */
export function existsSync(...args) {
  return fsExistsSync(...args);
}

/** 删除（同 node:fs.rmSync：recursive/force 由其 options 决定）。 */
export function rmSync(...args) {
  return fsRmSync(...args);
}

/** 复制（同 node:fs.cpSync）。 */
export function cpSync(...args) {
  return fsCpSync(...args);
}
```

