      out.push(t);
    }
  }
  // multi-line: find 'from "node:fs";' lines and walk back to 'import {'
  for (let i=0;i<lines.length;i++){
    if (/from "node:fs";/.test(lines[i].text)) {
      let j=i; while(j>0 && !/^import\b/.test(lines[j].text) && !/^const\b/.test(lines[j].text)) j--;
      if (lines[j].text !== lines[i].text) {
        out.push('MULTILINE['+lines[j].number+'-'+lines[i].number+']: '+lines.slice(j,i+1).map(l=>l.text).join('⏎'));
      }
    }
