217	/**
218	 * 原子写文件：先写临时文件（tmp 名带 pid+时间戳防并发碰撞）再 rename 覆盖，
219	 * 避免半写状态。注册表 / 自愈计数 / llm-pi-ai 段同步三处共用的写模式。
220	 */
221	function writeFileAtomic(file, data) {
222	  fs.mkdirSync(path.dirname(file), { recursive: true });
223	  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
224	  fs.writeFileSync(tmp, data, "utf8");
225	  fs.renameSync(tmp, file);
226	}
