228	/** 提取旧 settings 的 provider 配置段，保留各 provider 的全部字段。 */
229	function piAiSection(raw) {
230	  const SECTION_RE = /^llm-pi-ai\s*:/;
231	  const KEY_RE = /^[A-Za-z0-9_-]+\s*:/;
232	  const lines = raw.split(/\r?\n/);
233	  let start = -1;
234	  for (let i = 0; i < lines.length; i++) {
235	    if (SECTION_RE.test(lines[i])) { start = i; break; }
236	  }
237	  if (start === -1) return null;
238	  let end = lines.length;
239	  for (let i = start + 1; i < lines.length; i++) {
240	    // 下一个列 0 的键行（或文档分隔符 "---"）结束本段；EOF 也结束。
241	    if (KEY_RE.test(lines[i]) || lines[i].startsWith("---")) { end = i; break; }
242	  }
243	  // 段内容原样保留（含注释/空行），末尾空行收敛为最多一个（无空行时也保证结尾一个换行）。
244	  return lines.slice(start, end).join("\n").replace(/\n*$/, "\n");
245	}
