247	/**
248	 * 把全局 settings.yaml 的 `llm-pi-ai:` 段同步进 bot 的 settings.yaml（幂等）。
249	 * - 全局文件缺失/读取失败 → 静默 no-op（return false）。
250	 * - 全局无列 0 的 `llm-pi-ai:` 键行 → no-op。
251	 * - bot 文件已有该段 → no-op，绝不覆盖用户编辑。
252	 * - 否则把提取段原样追加并原子写入。返回是否写入了内容。
253	 */
254	function syncPiAiSection(root, botId) {
255	  let globalRaw;
256	  try {
257	    globalRaw = fs.readFileSync(path.join(root, "settings.yaml"), "utf8");
258	  } catch {
259	    return false; // 全局 settings.yaml 缺失/不可读 → 静默 no-op
260	  }
261	  const section = piAiSection(globalRaw);
262	  if (section === null) return false;
263	  const botSettingsPath = path.join(root, "profiles", botId, "settings.yaml");
264	  let botRaw;
