export function readdirSync(...args) {
  return fsReaddirSync(...args);
}

/** 取元数据（同 node:fs.statSync：跟随符号链接，路径不存在照常抛错）。 */
export function statSync(...args) {
  return fsStatSync(...args);
}

/** 存在性探测（同 node:fs.existsSync：返回布尔，不抛错）。 */
export function existsSync(...args) {
  return fsExistsSync(...args);
}

/** 删除（同 node:fs.rmSync：recursive／force 由其 options 决定）。 */
export function rmSync(...args) {
  return fsRmSync(...args);
}

/** 复制（同 node:fs.cpSync）。 */
export function cpSync(...args) {
  return fsCpSync(...args);
}

/**
 * 统一文件 IO 门 —— lib/safe-io.js。
 *
 * 目的：把 lib/ 下对 node:fs **常用读写原语**的直调收敛到一处——读
 * readFileSync／写 writeFileSync、appendFileSync／目录 mkdirSync、readdirSync、
 * rmSync、cpSync／查询 existsSync、statSync。这九个同步原语一律经本门转发；
 * 其余原语（open／close／read／write／fsync／rename／lstat／realpath／
 * mkdtemp／chmod 等）不在本门范围，仍直连 node:fs。
 *
 * 形态：逐原语的**薄封装**——同名同参透传，函数体内恰为一次 node:fs 转发，
 * 不加默认参数、不改返回值、不吞异常，故对调用方与直调 node:fs 行为完全一致。
 * 收益是收束「同一原语散落各处直调」：将来读写面要加统一策略（审计、权限、
 * 计量、降级），改本文件一处即覆盖全部调用点。
 *
