import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
const PRIMS = ["readFileSync","writeFileSync","appendFileSync","mkdirSync","readdirSync","statSync","existsSync","rmSync","cpSync"];
const root = "lib";
function walk(d){ const out=[]; for(const e of readdirSync(d)){ const p=join(d,e); const st=statSync(p); if(st.isDirectory()) out.push(...walk(p)); else if(/\.(js|cjs)$/.test(e)) out.push(p);} return out; }
const files = walk(root);
let bad = 0;
for (const f of files) {
  if (f === "lib/safe-io.js") continue;
  const text = readFileSync(f, "utf8");
  // 1) no listed primitive imported from node:fs in this file
  const fsImports = [...text.matchAll(/(?:import\s*\{([^}]*)\}\s*from\s*["']node:fs["']|require\(\s*["']node:fs["']\s*\))/g)];
  for (const m of fsImports) {
    const names = (m[1]||"").split(",").map(s=>s.trim().split(/\s+as\s+/)[0]).filter(Boolean);
    const hit = names.filter(n=>PRIMS.includes(n));
    if (hit.length) { console.log("DIRECT-FS", f, hit.join(",")); bad++; }
  }
  // 2) names imported from the gate (named import or destructuring require)
  const gateNames = new Set();
  for (const m of text.matchAll(/import\s*\{([^}]*)\}\s*from\s*["'][^"']*safe-io\.js["']/g))
    for (const s of m[1].split(",")) { const n = s.trim().split(/\s+as\s+/)[0].trim(); if(n) gateNames.add(s.trim().split(/\s+as\s+/).pop().trim()); }
  for (const m of text.matchAll(/const\s*\{([^}]*)\}\s*=\s*require\(\s*["'][^"']*safe-io\.js["']\s*\)/g))
    for (const s of m[1].split(",")) { const n=s.trim(); if(n) gateNames.add(n); }
  // 3) used identifiers among PRIMS must be imported from gate
  const body = text.replace(/import[^;]*?from\s*["'][^"']*safe-io\.js["'];?/g,"").replace(/const\s*\{[^}]*\}\s*=\s*require\(\s*["'][^"']*safe-io\.js["']\s*\);?/g,"");
  for (const p of PRIMS) {
    const re = new RegExp("\\b"+p+"\\b","g");
    const used = (body.match(re)||[]).length;
    if (used > 0 && !gateNames.has(p)) { console.log("UNROUTED-USE", f, p, "uses="+used, "gateImports="+[...gateNames].join("|")); bad++; }
  }
}
console.log(bad === 0 ? "STATIC CHECK OK: "+files.length+" lib files, no direct listed-primitive usage outside gate" : "STATIC CHECK FAILURES: "+bad);
`;
const w = await tools.write({ file_path: '.verify/check.mjs', content: script });
