   neo:'import {\n  closeSync, existsSync, fsyncSync, mkdirSync, openSync, readFileSync,\n  readdirSync, renameSync, rmSync, statSync, writeFileSync, writeSync\n} from "node:fs";' },
];
let ok=0; const errs:string[]=[];
for (const r of reverts) { try { await tools.edit({ file_path:r.file, old_string:r.old, new_string:r.neo }); ok++; } catch(e){ errs.push(r.file+': '+(e as Error).message); } }
