content.text:
1	/**
2	 * 统一文件 IO 门 —— lib/safe-io.js。
3	 *
4	 * 目的：把 lib/ 下对 node:fs **常用读写原语**的直调收敛到一处——读
5	 * readFileSync／写 writeFileSync、appendFileSync／目录 mkdirSync、readdirSync、
6	 * rmSync、cpSync／查询 existsSync、statSync。这九个同步原语一律经本门转发；
7	 * 其余原语（open／close／read／write／fsync／rename／lstat／realpath／
8	 * mkdtemp／chmod 等）不在本门范围，仍直连 node:fs。
9	 *
10	 * 形态：逐原语的**薄封装**——同名同参透传，函数体内恰为一次 node:fs 转发，
11	 * 不加默认参数、不改返回值、不吞异常，故对调用方与直调 node:fs 行为完全一致。
12	 * 收益是收束「同一原语散落各处直调」：将来读写面要加统一策略（审计、权限、
13	 * 计量、降级），改本文件一处即覆盖全部调用点。
14	 *
15	 * 加载：本文件为 ESM，lib/ 下 ESM 模块直接 import；lib/shared.cjs 经
16	 * require(ESM)（Node ≥ 22.12 默认支持，本模块无顶层 await）取同一份实现，
17	 * 使 CJS／ESM 两侧共用同一道门而非各存一份。
18	 *
19	 * 范围例外（冻结面，非疏漏）：`scripts/evidence-runner.mjs` 与
20	 * `scripts/evidence-packager.mjs` 的**执行依赖闭包**（sentinel provenance 的
21	 * sourceManifest：ledger-evidence╱org/store-base╱parity-manifest╱
22	 * sentinel-provenance╱sentinel-shadow╱evidence-packager）属证据冻结面，闭包
23	 * 文件仍直连 node:fs、不经本门——本模块若进闭包会改变 sourceManifest 的冻结
24	 * 清单，等同触碰冻结面（须新 runId 重采集）。该例外由 sentinel-provenance
25	 * 契约测试把守（闭包恰为固定清单）。
26	 */
27	import {
28	  appendFileSync as fsAppendFileSync,
29	  cpSync as fsCpSync,
30	  existsSync as fsExistsSync,
...
30	  existsSync as fsExistsSync,
31	  mkdirSync as fsMkdirSync,
32	  readFileSync as fsReadFileSync,
33	  readdirSync as fsReaddirSync,
34	  rmSync as fsRmSync,
35	  statSync as fsStatSync,
36	  writeFileSync as fsWriteFileSync
37	} from "node:fs";
38	
39	/** 读文件（同 node:fs.readFileSync：无 options 得 Buffer，给编码得 string）。 */
40	export function readFileSync(...args) {
41	  return fsReadFileSync(...args);
42	}
43	
44	/** 写文件（同 node:fs.writeFileSync：截断写；原子性仍由调用方 tmp+rename 负责）。 */
45	export function writeFileSync(...args) {
46	  return fsWriteFileSync(...args);
47	}
48	
49	/** 追加写（同 node:fs.appendFileSync）。 */
50	export function appendFileSync(...args) {
51	  return fsAppendFileSync(...args);
52	}
53	
54	/** 建目录（同 node:fs.mkdirSync：recursive 等由其 options 决定）。 */
55	export function mkdirSync(...args) {
56	  return fsMkdirSync(...args);
57	}
58	
59	/** 列目录（同 node:fs.readdirSync）。 */
60	export function readdirSync(...args) {
61	  return fsReaddirSync(...args);
62	}
63	
64	/** 取元数据（同 node:fs.statSync：跟随符号链接，路径不存在照常抛错）。 */
65	export function statSync(...args) {
66	  return fsStatSync(...args);
67	}
68	
69	/** 存在性探测（同 node:fs.existsSync：返回布尔，不抛错）。 */
70	export function existsSync(...args) {
71	  return fsExistsSync(...args);
72	}
