const path = await import("node:path");
const os = await import("node:os");
const crypto = await import("node:crypto");
const LIVE = path.join(os.homedir(), ".dsh/plugins/dsh-bots");
const NINE = ["readFileSync","writeFileSync","appendFileSync","mkdirSync","readdirSync","statSync","existsSync","rmSync","cpSync"];
const IMPORT_RE = /^import\s+(?:\{[^}]*\}\s*from\s*"[^"]+"|\S+\s+from\s*"[^"]+"|"[^"]+")\s*;\s*$/gm;
const files = ["lib/index.js","lib/mail-plane.js","lib/sentinel-runner.js","lib/knowledge.js","lib/org/capability-base.js","lib/org/probe.js","lib/lock-dir.js","lib/org/mail-shared-face.js","lib/org/knowledge-shared-face.js","lib/org/durability.js","lib/org/acceptance-coordinates.js","lib/stats.js","lib/org/deployment-inventory.js","lib/org/face-scan.js","lib/org/vocabulary-face.js","lib/pid-bind.js","lib/org/review-artifacts.js","lib/org/cutover.js","lib/bot-supervisor.js"];
let ok = true;
for (const f of files) {
  const orig = fs.readFileSync(path.join(LIVE, f), "utf8");
  const now = fs.readFileSync(f, "utf8");
  const bodyO = orig.replace(IMPORT_RE, "");
  const bodyN = now.replace(IMPORT_RE, "");
  const bodySame = bodyO === bodyN;
  // remaining node:fs import must not name any of the nine
  const fsImport = now.match(/import\s*\{([^}]*)\}\s*from\s*"node:fs";/);
  const leaked = fsImport ? fsImport[1].split(",").map((x)=>x.trim()).filter((n)=>NINE.includes(n)) : [];
  const hasGate = /from\s*"(\.\.?\/)?safe-io\.js";/.test(now);
  const good = bodySame && leaked.length === 0 && hasGate;
  if (!good) ok = false;
  console.log(`${good?"OK  ":"BAD "} ${f} bodySame=${bodySame} leaked=${JSON.stringify(leaked)} gate=${hasGate}`);
}
// CJS check
{
  const f="lib/shared.cjs";
  const orig = fs.readFileSync(path.join(LIVE,f),"utf8");
  const now = fs.readFileSync(f,"utf8");
  const norm = (t)=>t.replace('const safeIo = require("./safe-io.js");\n','').replace(/safeIo\.(readFileSync|writeFileSync|mkdirSync)\(/g,'fs.$1(');
  const same = norm(now)===orig;
  if(!same) ok=false;
  console.log(`${same?"OK  ":"BAD "} ${f} normalizedEqual=${same}`);
}
console.log("ALL_OK="+ok);","description":"Verify body invariance and import integrity"}

