{"code":"const fs = await import("node:fs");
const NINE = ["readFileSync","writeFileSync","appendFileSync","mkdirSync","readdirSync","statSync","existsSync","rmSync","cpSync"];
const targets = ["lib/index.js","lib/mail-plane.js","lib/sentinel-runner.js","lib/knowledge.js","lib/org/capability-base.js","lib/org/probe.js","lib/lock-dir.js","lib/org/mail-shared-face.js","lib/org/knowledge-shared-face.js","lib/org/durability.js","lib/org/acceptance-coordinates.js","lib/stats.js","lib/org/deployment-inventory.js","lib/org/face-scan.js","lib/org/vocabulary-face.js","lib/pid-bind.js","lib/org/review-artifacts.js","lib/org/cutover.js","lib/bot-supervisor.js","lib/shared.cjs"];
let ok = true;
for (const f of targets) {
  const src = fs.readFileSync(f, "utf8");
  const bare = new Set();
  for (const op of NINE) {
    const re = new RegExp(`(^|[^.\\w])${op}\\(`, "g");
    if (re.test(src)) bare.add(op);
  }
  const gate = new Set();
  const gm = src.match(/import\s*\{([^}]*)\}\s*from\s*"\.\.?\/safe-io\.js";/);
  if (gm) gm[1].split(",").map((x)=>x.trim()).forEach((n)=>gate.add(n));
  const cm = src.match(/safeIo\.(\w+)\(/g) || [];
  cm.forEach((m)=>gate.add(m.replace(/^safeIo\./,"").replace(/\($/,"")));
  const missing = [...bare].filter((n)=>!gate.has(n));
  if (missing.length) { ok = false; console.log(`UNCOVERED ${f}: ${missing.join(",")} (gate has: ${[...gate].join(",")})`); }
}
// no non-frozen file may import the nine from node:fs / require-destructure them
const chk = await tools.bash({command:`echo '--- node:fs imports still naming a nine (should be frozen files only):'
grep -rn 'from "node:fs"' lib --include='*.js' --include='*.cjs' | grep -E 'readFileSync|writeFileSync|appendFileSync|mkdirSync|readdirSync|statSync|existsSync|rmSync|cpSync' || echo '(none)'
echo '--- require("node:fs") sites in lib:'
grep -rn 'require("node:fs")' lib --include='*.cjs' --include='*.js' || echo '(none)'`, description:"Check no non-frozen file imports nine from node:fs"});
console.log("coverage: " + (ok ? "ALL 20 TARGET FILES ROUTED THROUGH GATE" : "SEE MISSING ABOVE"));
console.log(chk.kind==="foreground"?chk.stdout.text+chk.stderr.text:"?");","description":"Check gate coverage and stray node:fs imports"}

