{"code":"const fs = await import("node:fs");
const crypto = await import("node:crypto");
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");
const pkg = JSON.parse(fs.readFileSync("artifacts/packages/review-evidence-package-0010-405fdf54.json", "utf8"));
const manifest = pkg.executionEvidence.provenance.sourceManifest;
const frozen = manifest.map((e) => {
  const abs = e.path;
  const exists = fs.existsSync(abs);
  const cur = exists ? sha256(fs.readFileSync(abs)) : null;
  return { path: e.path, declared: e.sha256, current: cur, untouched: cur === e.sha256 };
});
console.log("冻结面（终版包 0010 sourceManifest 10 项逐字复算）:");
for (const f of frozen) console.log(`  ${f.untouched ? "UNTOUCHED" : "DIFFERS  "} ${f.path}`);
console.log("  untouched=" + frozen.filter((f) => f.untouched).length + "/" + frozen.length);","description":"Recompute frozen face against package manifest"}

