{"code":"const fs = await import("node:fs");
const path = await import("node:path");
const os = await import("node:os");
const crypto = await import("node:crypto");
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");
const LIVE = path.join(os.homedir(), ".dsh/plugins/dsh-bots");
const NINE = ["readFileSync","writeFileSync","appendFileSync","mkdirSync","readdirSync","statSync","existsSync","rmSync","cpSync"];
const IMPORT_RE = /^import\s+(?:\{[^}]*\}\s*from\s*"[^"]+"|\S+\s+from\s*"[^"]+"|"[^"]+")\s*;\s*$/gm;
const esm = ["lib/index.js","lib/mail-plane.js","lib/sentinel-runner.js","lib/knowledge.js","lib/org/capability-base.js","lib/org/probe.js","lib/lock-dir.js","lib/org/mail-shared-face.js","lib/org/knowledge-shared-face.js","lib/org/durability.js","lib/org/acceptance-coordinates.js","lib/stats.js","lib/org/deployment-inventory.js","lib/org/face-scan.js","lib/org/vocabulary-face.js","lib/pid-bind.js","lib/org/review-artifacts.js","lib/org/cutover.js","lib/bot-supervisor.js"];
const files = ["lib/safe-io.js", ...esm, "lib/shared.cjs"];
const perFile = [];
const norm = (t) => t.replace(IMPORT_RE, "").replace(/\n{2,}/g, "\n\n").trim();
for (const f of esm) {
  const before = fs.readFileSync(path.join(LIVE, f), "utf8");
  const after = fs.readFileSync(f, "utf8");
  perFile.push({ file: f, change: "import-only", beforeSha256: sha256(before), afterSha256: sha256(after), nonImportBodyIdentical: norm(before) === norm(after) });
}
{
  const before = fs.readFileSync(path.join(LIVE, "lib/shared.cjs"), "utf8");
  const after = fs.readFileSync("lib/shared.cjs", "utf8");
  const strip = (t) => t.replace('const safeIo = require("./safe-io.js");\n', "").replace(/safeIo\.(readFileSync|writeFileSync|mkdirSync)\(/g, "fs.$1(");
  perFile.push({ file: "lib/shared.cjs", change: "require+callsite-alias", beforeSha256: sha256(before), afterSha256: sha256(after), nonImportBodyIdentical: strip(after) === before });
}
const gate = fs.readFileSync("lib/safe-io.js", "utf8");
const failLines = (log) => fs.readFileSync(log, "utf8").split("\n").filter((l) => l.startsWith("✗")).map((l) => l.split(" — ")[0]).sort();
const baseFail = failLines(".scratch/tk-17b00002/baseline.log");
const afterFail = failLines(".scratch/tk-17b00002/after.log");
const summaryLine = (log) => fs.readFileSync(log, "utf8").trim().split("\n").pop();
const probes = [];
for (const index of [0,1,2,3]) {
  try { probes.push({ index, ...(await tools["evidence.probe"]({ taskId: "TK-17b00002", index })) }); }
  catch (e) { probes.push({ index, err: e.message.slice(0,200) }); }
}
const out = {
  task: "TK-17b00002",
  generatedAt: new Date().toISOString(),
  gate: { path: "lib/safe-io.js", bytes: Buffer.byteLength(gate), sha256: sha256(gate), exportFunctions: (gate.match(/export function/g)||[]).length, names: NINE },
  affected: { newFiles: 1, modifiedFiles: 20, referencingFilesInLib: 21, perFile },
  frozenFace: { source: "artifacts/packages/review-evidence-package-0010-405fdf54.json :: executionEvidence.provenance.sourceManifest", untouched: 10, total: 10 },
  regression: {
    command: "node tests/run.mjs",
    baseline: { summary: summaryLine(".scratch/tk-17b00002/baseline.log"), failingFiles: baseFail },
    after: { summary: summaryLine(".scratch/tk-17b00002/after.log"), failingFiles: afterFail },
    identicalFailureSet: JSON.stringify(baseFail) === JSON.stringify(afterFail)
  },
  probes
};
fs.writeFileSync(".scratch/tk-17b00002/verify-summary.json", JSON.stringify(out, null, 1) + "\n");
console.log("nonImportBodyIdentical: " + perFile.every((f) => f.nonImportBodyIdentical) + " (" + perFile.length + " files)");
console.log("failing set identical: " + out.regression.identicalFailureSet);
console.log("baseline: " + out.regression.baseline.summary + " | after: " + out.regression.after.summary);
console.log("failing files: " + afterFail.join(" ; "));
console.log("probes: " + probes.map((p) => `${p.index}:${p.ok === true ? "ok" : p.code || p.err}`).join(" | "));
console.log("summary bytes=" + fs.statSync(".scratch/tk-17b00002/verify-summary.json").size);","description":"Build machine-checkable verification summary"}

